import re,glob,collections,os
files=glob.glob('**/*.go',recursive=True)
text='\n'.join(open(f,errors='ignore').read() for f in files)
# funcs declarations
funcs=[]
for f in glob.glob('internal/**/*.go',recursive=True):
 s=open(f,errors='ignore').read()
 for m in re.finditer(r'(?m)^\s*func\s+(?:\([^\n]*\)\s*)?([A-Za-z_]\w*)\s*\(',s): funcs.append((m.group(1),f,m.start()))
counts=[]
for n,f,pos in funcs:
 c=len(re.findall(r'\b'+re.escape(n)+r'\s*\(',text))
 counts.append((c-1,n,f))
for x in sorted(counts,reverse=True)[:40]: print(x)
